// Package lru implements a fixed-capacity least-recently-used cache.
package lru

const nilSlot = -1

// entry is a node of the intrusive doubly linked list ordering slots by recency.
type entry struct {
	key, value string
	prev, next int32
}

// Cache is a fixed-capacity LRU cache mapping string keys to string values.
// Entries live in a preallocated slice and are linked by index, so every
// operation runs in O(1) expected time without per-operation allocation
// beyond the stored strings. A Cache is not safe for concurrent use.
type Cache struct {
	capacity int
	index    map[string]int32
	entries  []entry
	free     []int32
	head     int32 // most recently used
	tail     int32 // least recently used
}

// New returns an empty cache that holds at most capacity keys.
// It panics if capacity is less than 1.
func New(capacity int) *Cache {
	if capacity < 1 {
		panic("lru: capacity must be positive")
	}
	return &Cache{
		capacity: capacity,
		index:    make(map[string]int32, capacity+1),
		entries:  make([]entry, 0, capacity+1),
		head:     nilSlot,
		tail:     nilSlot,
	}
}

// Len reports the number of keys held.
func (c *Cache) Len() int { return len(c.index) }

// Get returns the value stored for key and marks it most recently used.
func (c *Cache) Get(key string) (string, bool) {
	slot, ok := c.index[key]
	if !ok {
		return "", false
	}
	c.moveToFront(slot)
	return c.entries[slot].value, true
}

// Set inserts or overwrites key, marks it most recently used, and evicts the
// least recently used key if the cache exceeds its capacity.
func (c *Cache) Set(key, value string) {
	if slot, ok := c.index[key]; ok {
		c.entries[slot].value = value
		c.moveToFront(slot)
		return
	}
	var slot int32
	if n := len(c.free); n > 0 {
		slot = c.free[n-1]
		c.free = c.free[:n-1]
		c.entries[slot] = entry{key: key, value: value}
	} else {
		slot = int32(len(c.entries))
		c.entries = append(c.entries, entry{key: key, value: value})
	}
	c.index[key] = slot
	c.pushFront(slot)
	if len(c.index) > c.capacity {
		c.remove(c.tail)
	}
}

// Delete removes key and reports whether it was present.
func (c *Cache) Delete(key string) bool {
	slot, ok := c.index[key]
	if !ok {
		return false
	}
	c.remove(slot)
	return true
}

func (c *Cache) remove(slot int32) {
	c.unlink(slot)
	delete(c.index, c.entries[slot].key)
	c.entries[slot] = entry{} // release the strings
	c.free = append(c.free, slot)
}

func (c *Cache) pushFront(slot int32) {
	e := &c.entries[slot]
	e.prev = nilSlot
	e.next = c.head
	if c.head != nilSlot {
		c.entries[c.head].prev = slot
	} else {
		c.tail = slot
	}
	c.head = slot
}

func (c *Cache) unlink(slot int32) {
	e := &c.entries[slot]
	if e.prev != nilSlot {
		c.entries[e.prev].next = e.next
	} else {
		c.head = e.next
	}
	if e.next != nilSlot {
		c.entries[e.next].prev = e.prev
	} else {
		c.tail = e.prev
	}
}

func (c *Cache) moveToFront(slot int32) {
	if slot == c.head {
		return
	}
	c.unlink(slot)
	c.pushFront(slot)
}

package lru

import "testing"

func TestEvictionOrder(t *testing.T) {
	c := New(2)
	c.Set("a", "1")
	c.Set("b", "2")
	if v, ok := c.Get("a"); !ok || v != "1" {
		t.Fatalf("Get(a) = %q, %v; want 1, true", v, ok)
	}
	c.Set("c", "3")
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
	if c.Len() != 2 {
		t.Fatalf("Len = %d; want 2", c.Len())
	}
}

func TestOverwriteRefreshes(t *testing.T) {
	c := New(2)
	c.Set("a", "1")
	c.Set("b", "2")
	c.Set("a", "9")
	c.Set("c", "3")
	if v, _ := c.Get("a"); v != "9" {
		t.Fatalf("Get(a) = %q; want 9", v)
	}
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
}

func TestDeleteReusesSlots(t *testing.T) {
	c := New(3)
	c.Set("x", "1")
	if !c.Delete("x") || c.Delete("x") {
		t.Fatal("Delete should report presence exactly once")
	}
	for i, k := range []string{"a", "b", "c", "d"} {
		c.Set(k, string(rune('0'+i)))
	}
	if c.Len() != 3 || len(c.entries) > 4 {
		t.Fatalf("Len = %d, slots = %d", c.Len(), len(c.entries))
	}
	if _, ok := c.Get("a"); ok {
		t.Fatal("a should have been evicted")
	}
}

// Command app simulates an LRU cache driven by commands on standard input.
//
// The first input line holds the capacity; each later line is one of
// SET <key> <value>, GET <key>, DEL <key> or SIZE.
package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"os"
	"strconv"

	"lru/internal/lru"
)

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "app:", err)
		os.Exit(1)
	}
}

func run(r io.Reader, w io.Writer) error {
	input, err := io.ReadAll(r)
	if err != nil {
		return err
	}
	first, rest, _ := bytes.Cut(input, []byte{'\n'})
	capacity, err := parseCapacity(first)
	if err != nil {
		return err
	}

	cache := lru.New(capacity)
	out := bufio.NewWriterSize(w, 1<<16)
	for len(rest) > 0 {
		var line []byte
		line, rest, _ = bytes.Cut(rest, []byte{'\n'})
		line = bytes.TrimSuffix(line, []byte{'\r'})
		if len(line) == 0 {
			continue
		}
		execute(cache, out, line)
	}
	return out.Flush()
}

// execute applies one command line to the cache, writing any output to out.
// Unknown or malformed commands are ignored.
func execute(cache *lru.Cache, out *bufio.Writer, line []byte) {
	cmd, args, _ := bytes.Cut(line, []byte{' '})
	switch string(cmd) {
	case "SET":
		key, value, ok := bytes.Cut(args, []byte{' '})
		if ok {
			cache.Set(string(key), string(value))
		}
	case "GET":
		if value, ok := cache.Get(string(args)); ok {
			out.WriteString(value)
		} else {
			out.WriteString("NULL")
		}
		out.WriteByte('\n')
	case "DEL":
		if cache.Delete(string(args)) {
			out.WriteString("1\n")
		} else {
			out.WriteString("0\n")
		}
	case "SIZE":
		out.WriteString(strconv.Itoa(cache.Len()))
		out.WriteByte('\n')
	}
}

// parseCapacity reads the leading integer of the first line, tolerating
// surrounding whitespace and trailing garbage.
func parseCapacity(line []byte) (int, error) {
	line = bytes.TrimLeft(line, " \t\r")
	end := 0
	for end < len(line) && line[end] >= '0' && line[end] <= '9' {
		end++
	}
	n, err := strconv.Atoi(string(line[:end]))
	if err != nil || n < 1 {
		return 0, fmt.Errorf("invalid capacity %q", line)
	}
	return n, nil
}
